-- Path of Building
--
-- Module: stable semantic identity for optimizer proposals.
-- Proposal labels and search-family metadata are deliberately kept outside the
-- identity so equivalent states generated by different families can be merged.
--
local sha = require("sha2")
local identity = { }

local NON_SEMANTIC_FIELDS = {
	label = true,
	description = true,
	rationale = true,
	island = true,
	isBaselineCandidate = true,
	sourceSignature = true,
	generationPhase = true,
	surrogateFeatures = true,
	canonicalHash = true,
	canonicalizationError = true,
	plannerFamilyOverride = true,
	requirementRepair = true,
	requirementRepairScore = true,
	proposalOrigins = true,
	proposalId = true,
	proposalIndex = true,
	candidateId = true,
	componentCandidateIds = true,
	kind = true,
	family = true,
	sourceFamily = true,
	origin = true,
	provenance = true,
	provenanceChain = true,
	targetId = true,
	targetIds = true,
	routeId = true,
	routeIds = true,
	routeCount = true,
	progressiveRouteBundle = true,
	socketRepairsComplete = true,
	socketRepairOnlySeed = true,
	archiveGateRepairAttempted = true,
	archiveGateRepairNeeds = true,
	hierarchicalExpert = true,
	hierarchicalExperts = true,
	hierarchicalCombination = true,
	hierarchicalCombinationKind = true,
}

local UNORDERED_ARRAY_FIELDS = {
	changedSlots = true,
	items = true,
	jewelVariants = true,
	anointVariants = true,
	generatedItems = true,
}

local SET_ARRAY_FIELDS = {
	nodeIds = true,
	removeNodeIds = true,
	changedSlots = true,
}

local function keyLess(left, right)
	local leftType, rightType = type(left), type(right)
	if leftType ~= rightType then return leftType < rightType end
	if leftType == "number" then return left < right end
	if leftType == "boolean" then return left == false and right == true end
	return tostring(left) < tostring(right)
end

local function encodeValue(value, stack, fieldName)
	local valueType = type(value)
	if valueType == "nil" then return "n" end
	if valueType == "boolean" then return value and "b1" or "b0" end
	if valueType == "number" then
		if value ~= value or value == math.huge or value == -math.huge then
			return nil, "Candidate identity contains a non-finite number"
		end
		local number = string.format("%.17g", value)
		return "d" .. tostring(#number) .. ":" .. number
	end
	if valueType == "string" then return "s" .. tostring(#value) .. ":" .. value end
	if valueType ~= "table" then
		return nil, "Candidate identity contains unsupported " .. valueType .. " data"
	end
	if stack[value] then return nil, "Candidate identity contains a cycle" end
	stack[value] = true

	local keys = { }
	for key in pairs(value) do
		if type(key) ~= "string" and type(key) ~= "number" and type(key) ~= "boolean" then
			stack[value] = nil
			return nil, "Candidate identity contains an unsupported table key"
		end
		keys[#keys + 1] = key
	end
	table.sort(keys, keyLess)

	local entries = { }
	if UNORDERED_ARRAY_FIELDS[fieldName] or SET_ARRAY_FIELDS[fieldName] then
		local normalized, seenValues = { }, { }
		for index, key in ipairs(keys) do
			if type(key) ~= "number" or key ~= index then
				stack[value] = nil
				return nil, "Candidate identity expected a dense array for " .. tostring(fieldName)
			end
			local encodedValue, valueError = encodeValue(value[key], stack)
			if not encodedValue then stack[value] = nil return nil, valueError end
			if not SET_ARRAY_FIELDS[fieldName] or not seenValues[encodedValue] then
				seenValues[encodedValue] = true
			normalized[#normalized + 1] = encodedValue
			end
		end
		table.sort(normalized)
		entries[1] = "u" .. tostring(#normalized) .. "[" .. table.concat(normalized, "") .. "]"
	else
		for _, key in ipairs(keys) do
			if not (fieldName == "candidate" and NON_SEMANTIC_FIELDS[key])
				and not (fieldName == "gearVariant" and (key == "inventorySearch" or key == "inventoryPair"
					or key == "inventoryRoutePair" or key == "syntheticSearch" or key == "catalystSearch"
					or key == "requirementRepair")) then
				local encodedKey, keyError = encodeValue(key, stack)
				local encodedValue, valueError = encodeValue(value[key], stack, key)
				if not encodedKey or not encodedValue then
					stack[value] = nil
					return nil, keyError or valueError
				end
				entries[#entries + 1] = encodedKey .. encodedValue
			end
		end
	end
	stack[value] = nil
	return "t" .. tostring(#entries) .. "{" .. table.concat(entries, "") .. "}"
end

function identity.HashContext(context)
	local encoded, encodeError = encodeValue(context or { }, { }, "context")
	if not encoded then return nil, encodeError end
	return sha.sha256("optimizer-candidate-context-v1\30" .. encoded)
end

local function generatedItemIdKey(value)
	local number = tonumber(value)
	if number and number == math.floor(number) then return "number:" .. string.format("%.0f", number) end
	return type(value) .. ":" .. tostring(value)
end

-- Generated PoB items are parsed native Item objects and can point back into
-- their ItemsTab/build graph. Their object identity is not proposal semantics.
-- Use the exact native item text and stable proposal fields, then replace the
-- run-local virtual IDs in slots/descriptors with that semantic fingerprint.
local function canonicalGearVariant(gear)
	if type(gear) ~= "table" then return gear end
	local canonical = { }
	for key, value in pairs(gear) do
		if key ~= "overrides" and key ~= "items" and key ~= "generatedItems" and key ~= "socketBinding" then
			canonical[key] = value
		end
	end

	local generatedIds, generatedItems = { }, { }
	if type(gear.generatedItems) == "table" then
		for _, entry in ipairs(gear.generatedItems) do
			if type(entry) ~= "table" then return nil, "Generated item identity contains a non-table entry" end
			local normalized = { }
			for key, value in pairs(entry) do
				if key ~= "item" and key ~= "tempId" and key ~= "itemId" then normalized[key] = value end
			end
			if type(entry.item) == "table" then
				if type(entry.item.raw) ~= "string" or entry.item.raw == "" then
					return nil, "Generated PoB item has no stable native raw identity"
				end
				normalized.nativeItemRaw = entry.item.raw
			end
			local encoded, encodeError = encodeValue(normalized, { }, "generatedItem")
			if not encoded then return nil, encodeError end
			local semanticId = "generated-item-v1:" .. sha.sha256(encoded)
			generatedItems[#generatedItems + 1] = normalized
			for _, id in ipairs({ entry.tempId, entry.itemId }) do
				if id ~= nil then generatedIds[generatedItemIdKey(id)] = semanticId end
			end
		end
		canonical.generatedItems = generatedItems
	end
	local function normalizeReference(id)
		if id == nil then return nil end
		return generatedIds[generatedItemIdKey(id)] or id
	end
	if type(gear.overrides) == "table" then
		canonical.overrides = { }
		for slot, itemId in pairs(gear.overrides) do canonical.overrides[slot] = normalizeReference(itemId) end
	end
	if type(gear.items) == "table" then
		canonical.items = { }
		for index, entry in ipairs(gear.items) do
			if type(entry) ~= "table" then
				canonical.items[index] = entry
			else
				local normalized = { }
				for key, value in pairs(entry) do
					if key ~= "itemId" and key ~= "tempId" then normalized[key] = value end
				end
				local itemId = entry.itemId or entry.tempId
				if itemId ~= nil then normalized.itemIdentity = normalizeReference(itemId) end
				canonical.items[index] = normalized
			end
		end
	end
	if type(gear.socketBinding) == "table" then
		canonical.socketBinding = { }
		for key, value in pairs(gear.socketBinding) do
			if key ~= "itemId" and key ~= "tempId" then canonical.socketBinding[key] = value end
		end
		local itemId = gear.socketBinding.itemId or gear.socketBinding.tempId
		if itemId ~= nil then canonical.socketBinding.itemIdentity = normalizeReference(itemId) end
	end
	return canonical
end

function identity.HashCandidate(contextHash, candidate)
	if type(contextHash) ~= "string" or contextHash == "" then
		return nil, "Candidate identity context hash is unavailable"
	end
	if type(candidate) ~= "table" then return nil, "Candidate is not a table" end
	local identityCandidate = candidate
	if type(candidate.gearVariant) == "table" then
		local gearVariant, gearError = canonicalGearVariant(candidate.gearVariant)
		if not gearVariant then return nil, gearError end
		identityCandidate = { }
		for key, value in pairs(candidate) do
			if key ~= "gearVariant" then identityCandidate[key] = value end
		end
		identityCandidate.gearVariant = gearVariant
	end
	local encoded, encodeError = encodeValue(identityCandidate, { }, "candidate")
	if not encoded then return nil, encodeError end
	return "candidate-v1:" .. sha.sha256(contextHash .. "\30" .. encoded)
end

-- After a socket-repair proposal has been composed with another mutation, the
-- search-origin flags below describe how the proposal was generated or counted;
-- they do not change the native items, sockets, skills, or tree that PoB applies.
-- Keep them in the first pass (some flags locate the repair seed), then omit them
-- only when checking whether post-composition candidates converge to one state.
local COMPOSED_GEAR_ORIGIN_FIELDS = {
	inventorySearch = true,
	inventoryPair = true,
	inventoryRoutePair = true,
	syntheticSearch = true,
	syntheticPair = true,
	syntheticTriple = true,
	catalystSearch = true,
	socketRepair = true,
	socketRepairOnly = true,
	requirementRepair = true,
}

function identity.HashComposedCandidate(contextHash, candidate)
	if type(candidate) ~= "table" then return nil, "Candidate is not a table" end
	local normalized = { }
	for key, value in pairs(candidate) do
		if key ~= "gearVariant" then normalized[key] = value end
	end
	if type(candidate.gearVariant) == "table" then
		normalized.gearVariant = { }
		for key, value in pairs(candidate.gearVariant) do
			-- `items` and `changedSlots` are presentation/indexing descriptions;
			-- the actual slot state is represented by overrides and generatedItems.
			if not COMPOSED_GEAR_ORIGIN_FIELDS[key] and key ~= "items" and key ~= "changedSlots" then
				normalized.gearVariant[key] = value
			end
		end
	end
	return identity.HashCandidate(contextHash, normalized)
end

-- Some valid PoB proposal metadata can contain cyclic native tables. Callers
-- may retain a bounded follow-up proposal with a stable run-local discriminator.
-- This is a unique fallback, not a claim that two unencodable states are equal.
function identity.UniqueFallbackHash(contextHash, discriminator)
	if type(contextHash) ~= "string" or contextHash == "" then
		return nil, "Candidate identity context hash is unavailable"
	end
	local discriminatorType = type(discriminator)
	if discriminatorType ~= "string" and discriminatorType ~= "number" and discriminatorType ~= "boolean" then
		return nil, "Candidate identity fallback discriminator must be a scalar"
	end
	local value = tostring(discriminator)
	return "candidate-v1:fallback:" .. sha.sha256(contextHash .. "\30uncanonicalized\30" .. value)
end

local function candidateFamily(candidate)
	-- Some Route Planner candidates carry a fixed native prerequisite (for
	-- example, a socket-repaired item) so PoB can evaluate their actual tree or
	-- gem mutation. Keep the originating proposal family for fair exact-budget
	-- interleaving instead of relabeling every such candidate as equipment or
	-- combined.
	local plannerFamilyOverride = type(candidate) == "table" and candidate.plannerFamilyOverride
	if type(plannerFamilyOverride) == "string" and plannerFamilyOverride ~= "" then
		return plannerFamilyOverride
	end
	if candidate.isBaselineCandidate then return "baseline" end
	local hasTree = #(type(candidate.nodeIds) == "table" and candidate.nodeIds or { }) > 0
		or #(type(candidate.removeNodeIds) == "table" and candidate.removeNodeIds or { }) > 0
	local hasGear = type(candidate.gearVariant) == "table"
	local hasSkills = candidate.gemVariant ~= nil or candidate.gemVariants ~= nil
	local hasConfiguration = candidate.configurationVariant ~= nil
	if hasTree and (hasGear or hasSkills or hasConfiguration) then return "combined" end
	if hasTree then return "tree" end
	if hasGear then return "equipment" end
	if hasSkills then return "skills" end
	if hasConfiguration then return "configuration" end
	return tostring(candidate.family or candidate.kind or candidate.generationPhase or "other")
end

local function addCount(counts, family)
	counts[family] = (counts[family] or 0) + 1
end

local function proposalOrigin(candidate)
	return {
		family = candidateFamily(candidate),
		label = tostring(candidate.label or "Unnamed proposal"):sub(1, 160),
		targetId = candidate.targetId,
	}
end

local function candidateOrigins(candidate)
	if type(candidate.proposalOrigins) == "table" then return candidate.proposalOrigins end
	return { proposalOrigin(candidate) }
end

local function appendOrigins(destination, origins)
	destination.proposalOrigins = destination.proposalOrigins or { }
	local seen = { }
	for _, origin in ipairs(destination.proposalOrigins) do
		seen[tostring(origin.family) .. "\30" .. tostring(origin.label) .. "\30" .. tostring(origin.targetId or "")] = true
	end
	for _, origin in ipairs(origins) do
		local key = tostring(origin.family) .. "\30" .. tostring(origin.label) .. "\30" .. tostring(origin.targetId or "")
		if not seen[key] then
			seen[key] = true
			destination.proposalOrigins[#destination.proposalOrigins + 1] = {
				family = origin.family,
				label = origin.label,
				targetId = origin.targetId,
			}
		end
	end
end

function identity.Deduplicate(candidates, contextHash, afterComposition)
	local unique, byHash, indexByHash = { }, { }, { }
	local beforeFamilies, afterFamilies = { }, { }
	local duplicates, fallbacks = 0, 0
	for _, candidate in ipairs(candidates or { }) do
		local family = candidateFamily(candidate)
		addCount(beforeFamilies, family)
		local hash, hashError
		if afterComposition then
			hash, hashError = identity.HashComposedCandidate(contextHash, candidate)
		else
			hash, hashError = identity.HashCandidate(contextHash, candidate)
		end
		if not hash then
			fallbacks = fallbacks + 1
			candidate.canonicalizationError = tostring(hashError or "Unknown canonicalization error"):sub(1, 200)
			unique[#unique + 1] = candidate
		else
			candidate.canonicalHash = hash
			local existing = byHash[hash]
			if existing then
				duplicates = duplicates + 1
				local existingOrigins = candidateOrigins(existing)
				local candidateProposalOrigins = candidateOrigins(candidate)
				local keeper = existing
				local keeperIndex = indexByHash[hash]
				if candidate.isBaselineCandidate and not existing.isBaselineCandidate then
					keeper = candidate
					unique[keeperIndex] = candidate
					byHash[hash] = candidate
				end
				appendOrigins(keeper, existingOrigins)
				appendOrigins(keeper, candidateProposalOrigins)
			else
				byHash[hash] = candidate
				indexByHash[hash] = #unique + 1
				unique[#unique + 1] = candidate
			end
		end
	end
	for _, candidate in ipairs(unique) do addCount(afterFamilies, candidateFamily(candidate)) end
	return unique, {
		composedCandidates = #(candidates or { }),
		uniqueCandidates = #unique,
		duplicateCandidatesDiscarded = duplicates,
		canonicalizationFallbacks = fallbacks,
		proposalFamilyCountsBefore = beforeFamilies,
		proposalFamilyCountsAfter = afterFamilies,
	}
end

-- Socket/link repair is composed into proposals after the first identity pass.
-- Distinct proposals can then converge to the same applied PoB state (for
-- example, an equipment search and a synthetic rare search selecting the same
-- repaired item). Re-run canonical identity after that composition and retain
-- both the original coverage and the second-pass accounting.
function identity.DeduplicateAfterComposition(candidates, contextHash, previousCoverage)
	local unique, composedCoverage = identity.Deduplicate(candidates, contextHash, true)
	previousCoverage = previousCoverage or { }
	return unique, {
		composedCandidates = previousCoverage.composedCandidates or composedCoverage.composedCandidates,
		uniqueCandidates = composedCoverage.uniqueCandidates,
		duplicateCandidatesDiscarded = (previousCoverage.duplicateCandidatesDiscarded or 0)
			+ composedCoverage.duplicateCandidatesDiscarded,
		canonicalizationFallbacks = previousCoverage.canonicalizationFallbacks or 0,
		proposalFamilyCountsBefore = previousCoverage.proposalFamilyCountsBefore
			or composedCoverage.proposalFamilyCountsBefore,
		proposalFamilyCountsAfter = composedCoverage.proposalFamilyCountsAfter,
		postCompositionUniqueCandidates = composedCoverage.uniqueCandidates,
		postCompositionDuplicatesDiscarded = composedCoverage.duplicateCandidatesDiscarded,
		postCompositionCanonicalizationFallbacks = composedCoverage.canonicalizationFallbacks,
	}
end

function identity.PrioritizeBaseline(candidates)
	local baselineIndex, baselineCount
	baselineCount = 0
	for index, candidate in ipairs(candidates or { }) do
		if candidate.isBaselineCandidate then
			baselineCount = baselineCount + 1
			if not baselineIndex then baselineIndex = index end
		end
	end
	if baselineIndex and baselineIndex ~= 1 then
		local baseline = table.remove(candidates, baselineIndex)
		table.insert(candidates, 1, baseline)
	end
	return baselineIndex and 1 or nil, baselineCount
end

function identity.Family(candidate)
	return candidateFamily(candidate)
end

-- Candidate reconstruction may replace its passive delta with PoB's resolved
-- allocation and attach a native gear proxy. Preserve the family and archive
-- provenance that were scheduled for exact evaluation before those mutations.
function identity.CaptureExactEvaluationMetadata(candidate)
	candidate = type(candidate) == "table" and candidate or { }
	return {
		family = candidateFamily(candidate),
		archivedRoutePattern = candidate.archivedRoutePattern == true,
		archivedRouteComposition = candidate.archivedRouteComposition == true,
	}
end

local DEFAULT_EXACT_FAMILY_ORDER = { "equipment", "skills", "combined", "tree", "configuration", "other" }

-- Keep the ranked order within each mutation family, while round-robining the
-- families before the exact-evaluation cap. A large proposal pool must not let
-- one high-volume generator consume every native PoB calculation slot.
function identity.InterleaveFamilies(candidates, options)
	options = options or { }
	local ordered, baseline, reserved, queues = { }, { }, { }, { }
	local candidateSet, reservedSet = { }, { }
	for _, candidate in ipairs(options.reservedCandidates or { }) do
		if type(candidate) == "table" then reservedSet[candidate] = true end
	end
	for _, candidate in ipairs(candidates or { }) do
		candidateSet[candidate] = true
		if candidate.isBaselineCandidate then
			baseline[#baseline + 1] = candidate
		elseif reservedSet[candidate] then
			reserved[#reserved + 1] = candidate
		else
			local family = candidateFamily(candidate)
			queues[family] = queues[family] or { }
			queues[family][#queues[family] + 1] = candidate
		end
	end
	local seenFamily, familyOrder = { }, { }
	for _, family in ipairs(options.familyOrder or DEFAULT_EXACT_FAMILY_ORDER) do
		if type(family) == "string" and not seenFamily[family] then
			seenFamily[family] = true
			familyOrder[#familyOrder + 1] = family
		end
	end
	local additionalFamilies = { }
	for family in pairs(queues) do
		if not seenFamily[family] then additionalFamilies[#additionalFamilies + 1] = family end
	end
	table.sort(additionalFamilies)
	for _, family in ipairs(additionalFamilies) do familyOrder[#familyOrder + 1] = family end

	for _, candidate in ipairs(baseline) do ordered[#ordered + 1] = candidate end
	for _, candidate in ipairs(reserved) do ordered[#ordered + 1] = candidate end
	local offsets = { }
	for _, family in ipairs(familyOrder) do offsets[family] = 1 end
	local remaining = 0
	for _, queue in pairs(queues) do remaining = remaining + #queue end
	while remaining > 0 do
		local progressed = false
		for _, family in ipairs(familyOrder) do
			local queue = queues[family]
			local index = offsets[family] or 1
			if queue and index <= #queue then
				ordered[#ordered + 1] = queue[index]
				offsets[family] = index + 1
				remaining = remaining - 1
				progressed = true
			end
		end
		if not progressed then break end
	end
	-- Keep any future/unclassified candidate once, even if it was duplicated in
	-- the reserved list or a malformed family queue.
	local final, finalSeen = { }, { }
	for _, candidate in ipairs(ordered) do
		if candidateSet[candidate] and not finalSeen[candidate] then
			finalSeen[candidate] = true
			final[#final + 1] = candidate
		end
	end
	if #final < #(candidates or { }) then
		for _, candidate in ipairs(candidates or { }) do
			if not finalSeen[candidate] then finalSeen[candidate] = true; final[#final + 1] = candidate end
		end
	end
	local candidateCount = #final
	local reordered = 0
	for index, candidate in ipairs(final) do
		if candidate ~= (candidates or { })[index] then reordered = reordered + 1 end
	end
	local retentionLimit = tonumber(options.retentionLimit)
	if retentionLimit and retentionLimit >= 0 then
		retentionLimit = math.floor(retentionLimit)
		-- Baseline and explicitly reserved proposals are already at the front of
		-- the exact queue. Never cut through that protected prefix.
		retentionLimit = math.max(retentionLimit, #baseline + #reserved)
		for index = #final, retentionLimit + 1, -1 do final[index] = nil end
	else
		retentionLimit = nil
	end
	local windowCounts, windowSequence = { }, { }
	local windowSize = math.min(#final, math.max(0, math.floor(tonumber(options.budget) or candidateCount)))
	for index = 1, windowSize do
		local family = candidateFamily(final[index])
		windowCounts[family] = (windowCounts[family] or 0) + 1
		if #windowSequence < 64 then windowSequence[#windowSequence + 1] = family end
	end
	local diversity = 0
	for _ in pairs(windowCounts) do diversity = diversity + 1 end
	return final, {
		status = "round_robin_by_mutation_family",
		candidateCount = candidateCount,
		retainedCandidateCount = #final,
		exactQueueLimit = retentionLimit,
		discardedBeyondRetentionLimit = math.max(0, candidateCount - #final),
		baselineCandidatesReserved = #baseline,
		priorityCandidatesReserved = #reserved,
		familyOrder = familyOrder,
		windowSize = windowSize,
		windowFamilyCounts = windowCounts,
		windowFamilyDiversity = diversity,
		windowFamilySequence = windowSequence,
		reorderedCandidates = reordered,
	}
end

function identity.ReplaceScheduledWithRepairs(candidates, scheduledLookup, repairs, contextHash, proposalBudget)
	local active, removedScheduled = { }, 0
	for _, candidate in ipairs(candidates or { }) do
		if scheduledLookup and scheduledLookup[candidate] then
			removedScheduled = removedScheduled + 1
		else
			active[#active + 1] = candidate
		end
	end
	local activeUnique, activeCoverage = identity.Deduplicate(active, contextHash)
	local repairInsertIndex = 1
	for index, candidate in ipairs(activeUnique) do
		if candidate.isBaselineCandidate then repairInsertIndex = index + 1; break end
	end
	local repairLookup = { }
	for _, candidate in ipairs(repairs or { }) do repairLookup[candidate] = true end
	for index = #(repairs or { }), 1, -1 do
		table.insert(activeUnique, repairInsertIndex, repairs[index])
	end
	local composedCandidates = #activeUnique
	local uniqueCandidates, repairCoverage = identity.Deduplicate(activeUnique, contextHash)
	local budget = math.max(0, math.floor(tonumber(proposalBudget) or #uniqueCandidates))
	local discardedByProposalBudget = math.max(0, #uniqueCandidates - budget)
	if discardedByProposalBudget > 0 then
		for index = #uniqueCandidates, budget + 1, -1 do uniqueCandidates[index] = nil end
	end
	local retainedRepairCandidateList = { }
	for _, candidate in ipairs(uniqueCandidates) do
		if repairLookup[candidate] then retainedRepairCandidateList[#retainedRepairCandidateList + 1] = candidate end
	end
	return uniqueCandidates, {
		removedScheduledCandidates = removedScheduled,
		activeUniqueCandidates = activeCoverage.uniqueCandidates,
		composedCandidates = composedCandidates,
		uniqueCandidates = repairCoverage.uniqueCandidates,
		newUniqueCandidates = math.max(0, repairCoverage.uniqueCandidates - activeCoverage.uniqueCandidates),
		duplicateCandidatesDiscarded = repairCoverage.duplicateCandidatesDiscarded,
		discardedByProposalBudget = discardedByProposalBudget,
		retainedCandidates = #uniqueCandidates,
		retainedRepairCandidates = #retainedRepairCandidateList,
		retainedRepairCandidateList = retainedRepairCandidateList,
		canonicalizationFallbacks = repairCoverage.canonicalizationFallbacks,
	}
end

return identity
